//! Room properties, view drawings and schedule membership.
use serde_json::{json,Value};
use openarch_model::{Document,Element,Id};
use openarch_model::rooms::{Room,RoomStatus};
use crate::{Session,Res};

fn text(label:&str,path:&str,value:&str)->Value{json!({"label":label,"path":path,"kind":"text","value":value})}
fn num(label:&str,path:&str,value:f64)->Value{json!({"label":label,"path":path,"kind":"number","raw":value,"value":value.to_string()})}
fn ro(label:&str,value:String,raw:Option<f64>,unit:&str)->Value{json!({"label":label,"kind":"ro","value":value,"raw":raw,"parameter_unit":unit})}
pub(crate) fn room_properties(d:&Document,id:Id,r:&Room)->Value{
    let c=d.room_calculation(id).unwrap();let state=match c.status{RoomStatus::Placed=>"Placed",RoomStatus::NotPlaced=>"Not Placed",RoomStatus::NotEnclosed=>"Not Enclosed",RoomStatus::Redundant=>"Redundant"};
    let dims=vec![ro("Area",if c.status==RoomStatus::Placed{format!("{:.2} m²",c.area_mm2/1e6)}else{state.into()},(c.status==RoomStatus::Placed).then_some(c.area_mm2/1e6),"area"),ro("Perimeter",format!("{:.0}",c.perimeter_mm),(c.status==RoomStatus::Placed).then_some(c.perimeter_mm),"length"),ro("Unbounded Height",format!("{:.0}",c.height_mm),Some(c.height_mm),"length"),ro("Volume",c.volume_mm3.map(|v|format!("{:.2} m³",v/1e9)).unwrap_or("Not Calculated".into()),c.volume_mm3.map(|v|v/1e9),"volume")];
    let mut identity=vec![text("Number","number",&r.number),text("Name","name",&r.name),text("Comments","comments",&r.comments),text("Occupancy","occupancy",&r.occupancy),text("Department","department",&r.department),text("Occupant","occupant",&r.occupant),ro("Status",state.into(),None,"text")];
    if d.rooms().iter().any(|(other,room)|*other!=id&&room.number==r.number){identity.push(ro("Warning","Room number is also used by another room.".into(),None,"text"));}
    json!({"id":id,"kind":"Room","category":"Rooms","title":format!("Room: {} {}",r.number,r.name),"type_label":"Room","target":{"method":"patch_room","id":id},"groups":[
        {"name":"Constraints","rows":[ro("Level",d.level(r.level).map_or(String::new(),|l|l.name.clone()),None,"text"),{"label":"Upper Limit","kind":"select","value":r.upper_level.and_then(|id|d.level(id)).map(|l|l.name.clone()).unwrap_or("Base Level".into()),"options":std::iter::once(json!({"label":"Base Level","patch":{"upper_level":null},"selected":r.upper_level.is_none()})).chain(d.levels().iter().map(|(id,l)|json!({"label":l.name,"patch":{"upper_level":id},"selected":r.upper_level==Some(*id)}))).collect::<Vec<_>>()},num("Limit Offset","limit_offset_mm",r.limit_offset_mm),num("Base Offset","base_offset_mm",r.base_offset_mm),{"label":"Pinned","kind":"bool","path":"pinned","raw":r.pinned,"value":if r.pinned{"Yes"}else{"No"}}]},
        {"name":"Dimensions","rows":dims},{"name":"Identity Data","rows":identity},{"name":"Materials and Finishes","rows":[text("Base Finish","base_finish",&r.base_finish),text("Floor Finish","floor_finish",&r.floor_finish),text("Wall Finish","wall_finish",&r.wall_finish),text("Ceiling Finish","ceiling_finish",&r.ceiling_finish)]}]})
}

pub(crate) fn drawing(d:&Document,view:Id)->Value{
    let Some(v)=d.view(view)else{return json!({})};let Some(level)=v.level else{return json!({})};let settings=d.effective_settings(view).unwrap_or_default();let shown=|category:&str|settings.overrides.model.get(category).or_else(||settings.overrides.annotation.get(category)).is_none_or(|o|o.visible);
    let rooms:Vec<_>=d.rooms().into_iter().filter(|(id,r)|r.level==level&&r.at.is_some()&&shown("Rooms")&&!v.hidden_elements.contains(id)).map(|(id,r)|{let c=d.room_calculation(id).unwrap();json!({"id":id,"number":r.number,"name":r.name,"at":r.at,"pinned":r.pinned,"status":c.status,"rings":c.region.as_ref().map(|region|std::iter::once(&region.outer).chain(&region.holes).map(|r|r.iter().map(|p|[p.x,p.y]).collect::<Vec<_>>()).collect::<Vec<_>>()).unwrap_or_default()})}).collect();
    let tags:Vec<_>=d.room_tags(view).into_iter().filter(|(id,_)|shown("Room Tags")&&!v.hidden_elements.contains(id)).map(|(id,t)|{let fam=t.family.and_then(|id|d.annotation_family(id));json!({"id":id,"room":t.room,"at":t.at,"pinned":t.pinned,"leader":t.leader,"family":fam.map(|f|d.symbol_drawing(f,false)),"labels":d.room_tag_labels(t),"room_at":d.room(t.room).and_then(|r|r.at)})}).collect();
    let separators:Vec<_>=d.iter().filter_map(|(id,e)|if let Element::RoomSeparation(s)=e{(s.level==level&&shown("Room Separation")&&!v.hidden_elements.contains(&id)).then(||json!({"id":id,"pinned":s.pinned,"curve":s.curve,"pts":s.curve.tessellate(1.5).iter().map(|p|[p.x,p.y]).collect::<Vec<_>>()}))}else{None}).collect();
    json!({"rooms":rooms,"room_tags":tags,"room_separators":separators})
}

impl Session{
    pub(crate) fn room_fields()->Vec<Value>{[("Number","text"),("Name","text"),("Comments","text"),("Occupancy","text"),("Department","text"),("Occupant","text"),("Base Finish","text"),("Floor Finish","text"),("Wall Finish","text"),("Ceiling Finish","text"),("Level","text"),("Area","area"),("Perimeter","length"),("Volume","volume"),("Unbounded Height","length"),("Status","text")].into_iter().map(|(name,unit)|json!({"name":name,"kind":"instance","unit":unit})).collect()}
    pub(crate) fn add_room_api(&mut self,p:&Value)->Res{let level=p["level_id"].as_u64().ok_or("Choose a level")?;let at=if p["point"].is_array(){Some(crate::point_of(&p["point"])?) }else{None};let view=p["view_id"].as_u64().filter(|_|p["tag"].as_bool().unwrap_or(true));let id=self.doc.add_room(level,at,view)?;Ok(json!({"id":id}))}
    pub(crate) fn room_tag_props(&self,id:Id,t:&openarch_model::rooms::RoomTag)->Value{json!({"id":id,"kind":"RoomTag","type_label":"Room Tag","title":"Room Tag","target":{"method":"patch_room_tag","id":id},"groups":[{"name":"Identity Data","rows":[ro("Room",self.doc.room(t.room).map_or(String::new(),|r|format!("{} {}",r.number,r.name)),None,"text")]},{"name":"Graphics","rows":[{"label":"Leader","kind":"bool","path":"leader","raw":t.leader,"value":if t.leader{"Yes"}else{"No"}},{"label":"Family","kind":"select","value":t.family.and_then(|id|self.doc.annotation_family(id)).map(|f|f.name.clone()).unwrap_or_default(),"options":self.doc.annotation_families().into_iter().filter(|(_,f)|f.kind==openarch_model::annotation::AnnotationKind::RoomTag).map(|(id,f)|json!({"label":f.name,"patch":{"family":id},"selected":Some(id)==t.family})).collect::<Vec<_>>()}]}]})}
    pub(crate) fn component_room_fields(&self,id:Id)->Vec<Value>{let(room,from,to)=self.doc.instance_rooms(id);let mut rows=vec![];for(prefix,id)in[("Room",room.or(to).or(from)),("From Room",from),("To Room",to)]{for(name,path)in[("Number","number"),("Name","name"),("Department","department"),("Occupancy","occupancy")]{let value=id.and_then(|id|self.doc.room(id)).map(|r|match path{"number"=>r.number.clone(),"name"=>r.name.clone(),"department"=>r.department.clone(),_=>r.occupancy.clone()}).unwrap_or_default();rows.push(ro(&format!("{prefix}: {name}"),value,None,"text"));}}rows}
    pub(crate) fn prepare_embedded(&self,mut def:openarch_model::schedule::ScheduleDef)->Result<openarch_model::schedule::ScheduleDef,String>{
        if let Some(child)=&mut def.embedded{if def.category!="Rooms"||def.key.is_some()||child.key.is_some()||child.embedded.is_some()||!openarch_model::FamilyCategory::all().iter().any(|c|c.label()==child.category){return Err("Embed one model category in a room schedule.".into());}let units=self.schedule_param_units(&child.category);for f in &mut child.fields{if matches!(f.kind,openarch_model::schedule::FieldKind::Instance|openarch_model::schedule::FieldKind::Type){f.unit=units.get(&f.name).copied().unwrap_or(openarch_model::schedule::Unit::Text);}}child.check(&|f|units.get(&f.name).copied().unwrap_or(openarch_model::schedule::Unit::Text))?;}Ok(def)
    }
    pub(crate) fn embed_room_contents(&self,view:Id,def:&openarch_model::schedule::ScheduleDef,columns:&mut Vec<Value>,rows:&mut Vec<Value>,visible:Option<&std::collections::HashSet<Id>>)->Result<(),String>{
        let Some(child)=&def.embedded else{return Ok(())};let ids:Vec<_>=self.doc.iter().filter(|(id,_)|self.schedule_category(*id).as_deref()==Some(&child.category)).map(|(id,_)|id).collect();let parent_columns=columns.len();let all:std::collections::HashSet<_>=ids.iter().copied().collect();let template=self.schedule_table_definition(view,Some(&all),Some(child))?;let child_columns=template["columns"].as_array().unwrap();for c in child_columns{let mut c=c.clone();c["heading"]=json!(format!("{}: {}",child.category,c["heading"].as_str().unwrap_or("")));columns.push(c);}
        let mut output=vec![];for mut row in std::mem::take(rows){let parent=row["ids"].as_array().cloned().unwrap_or_default();let item=row["kind"]=="item";row["cells"].as_array_mut().unwrap().extend((0..child_columns.len()).map(|_|json!({"text":""})));output.push(row);if !item{continue;}let contained:std::collections::HashSet<_>=ids.iter().filter(|id|visible.is_none_or(|v|v.contains(id))&&{let(r,f,t)=self.doc.instance_rooms(**id);r.or(t).or(f).is_some_and(|id|parent.iter().any(|p|p.as_u64()==Some(id)))}).copied().collect();let table=self.schedule_table_definition(view,Some(&contained),Some(child))?;
            for r in table["rows"].as_array().into_iter().flatten(){let mut r=r.clone();let cells=r["cells"].as_array().cloned().unwrap_or_default();r["cells"]=json!((0..parent_columns).map(|_|json!({"text":""})).chain(cells).collect::<Vec<_>>());r["embedded"]=json!(true);if r["kind"]=="header"{r["kind"]=json!("item");}output.push(r);}
        }*rows=output;Ok(())
    }
}
